function useOnline() {
  const [online, setOnline] = useState(navigator.onLine);
  useEffect(() => {
    const update = () => setOnline(navigator.onLine);
    window.addEventListener('online', update);
    window.addEventListener('offline', update);
    return () => {
      window.removeEventListener('online', update);
      window.removeEventListener('offline', update);
    };
  }, []);
  return online;
}

export function Rail({ me, workspaces, workspace, onWorkspace, filter, onFilter, connected, onSignOut }: Props) {
  const online = useOnline();
  const status = !online ? 'offline' : connected ? 'live' : 'reconnecting';
  const statusText = { live: 'Live', reconnecting: 'Reconnecting...', offline: 'Offline' }[status];

  return (
    <nav className="rail" aria-label="Workspace">
      <div className="rail-brand"><BrandMark size={32} /></div>
      <div className="rail-group">
        <button
          className="rail-btn"
          aria-label="Inbox"
          title="Inbox"
          aria-current={filter !== 'mine' ? 'page' : undefined}
          onClick={() => onFilter('open')}
        >
          <InboxIcon size={20} />
        </button>
        <button
          className="rail-btn"
          aria-label="Mine"
          title="Assigned to me"
          aria-current={filter === 'mine' ? 'page' : undefined}
          onClick={() => onFilter('mine')}
        >
          <UserIcon size={20} />
        </button>
      </div>
      <div className="rail-group rail-workspaces" role="group" aria-label="Workspaces">
        {workspaces.map((w) => (
          <button
            key={w.id}
            className="rail-btn rail-ws"
            aria-pressed={w.id === workspace}
            aria-label={workspaceName(w.id)}
            title={workspaceName(w.id)}
            onClick={() => onWorkspace(w.id)}
          >
            {workspaceName(w.id).charAt(0)}
          </button>
        ))}
      </div>
      <div className="rail-bottom">
        <span className={`conn conn-${status}`} role="img" aria-label={`Connection: ${statusText}`} title={statusText} />
        <UserMenu me={me} onSignOut={onSignOut} />
      </div>
    </nav>
  );
}

function UserMenu({ me, onSignOut }: { me: Me; onSignOut: () => void }) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onPointer = (e: MouseEvent) => {
      if (!root.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', onPointer);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onPointer);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  return (
    <div className="user-menu" ref={root}>
      <button
        className="rail-avatar"
        aria-label="Account menu"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <Avatar label={me.name} seed={me.sub} size={32} />
      </button>
      {open && (
        <div className="menu" role="menu">
          <div className="menu-head">
            <strong>{me.name}</strong>
            <span>{me.email}</span>
          </div>
          <button className="menu-item" role="menuitem" onClick={onSignOut}>Sign out</button>
        </div>
      )}
    </div>
  );
}
import { useEffect, useState } from 'react';
import { formatPhone } from '../format';
import { PeopleContext, usePeople } from '../people';
import { useUnread } from '../unread';
import { useLatest } from '../useLatest';
import { useSocket } from '../useSocket';
import type { Frame, Me } from '../types';
import { Inbox, type Filter } from './Inbox';
import { Rail } from './Rail';
import { Thread, type Panel } from './Thread';

interface Props {
  me: Me;
  workspaces: Me['workspaces'];
  workspace: string;
  isAdmin: boolean;
  onWorkspace: (id: string) => void;
  onSignOut: () => void;
}

export function Workspace({ me, workspaces, workspace, isAdmin, onWorkspace, onSignOut }: Props) {
  const { connected, epoch, subscribe } = useSocket(workspace);
  const people = usePeople(workspace, me);
  const unread = useUnread(workspace);
  const [filter, setFilter] = useState<Filter>('open');
  const [contact, setContact] = useState<string | null>(null);
  const [panel, setPanel] = useState<Panel | null>(null);
  const [announcement, setAnnouncement] = useState('');
  const openContact = useLatest(contact);

  const handleFrame = useLatest((frame: Frame) => {
    switch (frame.type) {
      case 'message.inbound':
        if (frame.contact === openContact.current) unread.markSeen(frame.contact);
        else unread.markInbound(frame.contact);
        setAnnouncement(`New message from ${formatPhone(frame.contact)}: ${frame.text}`);
        break;
      case 'message.outbound':
        people.seen(frame.sender);
        break;
      case 'conversation.assigned':
        people.seen(frame.assignee);
        break;
      case 'note.added':
        people.seen(frame.author);
        break;
    }
  });

  useEffect(() => subscribe((frame) => handleFrame.current(frame)), [subscribe, handleFrame]);

  useEffect(() => {
    if (!panel) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setPanel(null);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [panel]);

  function select(next: string) {
    unread.markSeen(next);
    setContact(next);
  }

  const showPanel = contact !== null && panel !== null;

  return (
    <PeopleContext.Provider value={people}>
      <a className="skip-link" href="#thread">Skip to conversation</a>
      <div className={`shell${showPanel ? ' info-open' : ''}`}>
        <Rail
          me={me}
          workspaces={workspaces}
          workspace={workspace}
          onWorkspace={onWorkspace}
          filter={filter}
          onFilter={setFilter}
          connected={connected}
          onSignOut={onSignOut}
        />
        <Inbox
          me={me}
          workspace={workspace}
          filter={filter}
          onFilter={setFilter}
          selected={contact}
          onSelect={select}
          isUnread={unread.isUnread}
          subscribe={subscribe}
          epoch={epoch}
        />
        {contact ? (
          <Thread
            key={contact}
            me={me}
            workspace={workspace}
            contact={contact}
            isAdmin={isAdmin}
            subscribe={subscribe}
            epoch={epoch}
            panel={panel}
            onPanel={setPanel}
            onBack={() => setContact(null)}
          />
        ) : (
          <main className="thread-empty" id="thread" tabIndex={-1} aria-label="Conversation">
            <p>Pick a conversation to start.</p>
          </main>
        )}
        {showPanel && <div className="scrim" onClick={() => setPanel(null)} />}
      </div>
      <div className="visually-hidden" aria-live="polite">{announcement}</div>
    </PeopleContext.Provider>
  );
}
import { useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react';
import { SendIcon } from './icons';

const MAX_LENGTH = 4000;
const SHOW_COUNTER = MAX_LENGTH * 0.8;
const WARN_COUNTER = MAX_LENGTH * 0.9;

interface Props {
  onSend: (text: string) => void;
  disabledReason?: string;
}

export function ReplyBox({ onSend, disabledReason }: Props) {
  const [text, setText] = useState('');
  const field = useRef<HTMLTextAreaElement>(null);
  const trimmed = text.trim();
  const over = text.length > MAX_LENGTH;
  const disabled = Boolean(disabledReason);

  useLayoutEffect(() => {
    const el = field.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${el.scrollHeight}px`;
  }, [text]);

  function send() {
    if (!trimmed || over || disabled) return;
    onSend(trimmed);
    setText('');
  }

  function onKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault();
      send();
    }
  }

  const sendBlocked = disabled || !trimmed || over;
  const sendReason = disabledReason ?? (over ? `Messages can be up to ${MAX_LENGTH} characters` : !trimmed ? 'Type a message to send' : undefined);
  const counterTone = over ? 'danger' : text.length >= WARN_COUNTER ? 'warning' : '';

  return (
    <form
      className="composer"
      onSubmit={(e) => {
        e.preventDefault();
        send();
      }}
    >
      <div className={`composer-card${disabled ? ' is-disabled' : ''}`}>
        {disabledReason && <p className="composer-reason">{disabledReason}</p>}
        <label htmlFor="reply-text" className="visually-hidden">Reply</label>
        <textarea
          id="reply-text"
          ref={field}
          value={text}
          rows={1}
          disabled={disabled}
          placeholder="Write a reply"
          onChange={(e) => setText(e.target.value)}
          onKeyDown={onKeyDown}
        />
        <div className="composer-foot">
          <span className="composer-hint">Enter to send, Shift+Enter for a new line</span>
          {text.length >= SHOW_COUNTER && (
            <span className={`composer-count ${counterTone}`}>{text.length} / {MAX_LENGTH}</span>
          )}
          <button className="btn btn-primary btn-send" type="submit" disabled={sendBlocked} title={sendReason}>
            <SendIcon size={16} />
            <span className="visually-hidden">Send</span>
          </button>
        </div>
      </div>
    </form>
  );
}
