        <div>
          <dt>Seats</dt>
          <dd>{subscribed ? seatLabel(billing.seats) : 'None yet'}</dd>
        </div>
        <div>
          <dt>Monthly cost</dt>
          <dd>{subscribed ? money(monthly) : money(0)}</dd>
