import { useState, type FormEvent } from 'react';
import {
  PaymentError,
  formatCardNumber,
  formatExpiry,
  hasErrors,
  subscribe,
  tokenizeCard,
  totalLine,
  validateCard,
  digitsOnly,
  type Billing,
  type Card,
  type CardErrors,
} from '../../billing';
import { errorText } from '../../api';
import { useToast } from '../Toasts';
import { SeatStepper } from './SeatStepper';
