.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3); }
.field-error { font: var(--text-sm); color: var(--danger); }
.input {
  width: 100%;
  height: 40px;
  padding: 0 var(--space-3);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-2);
  background: var(--surface);
  font: var(--text-base);
}
.input:focus-visible { outline: none; border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft), 0 0 0 1px var(--brand); }
.input:disabled { background: var(--surface-2); color: var(--text-muted); }
.input[aria-invalid="true"] { border-color: var(--danger); }

.stepper { display: flex; align-items: center; gap: var(--space-2); }
.stepper-btn { width: 40px; height: 40px; padding: 0; font-size: 18px; }
.stepper-input { width: 80px; text-align: center; }

.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover:not(:disabled) { background: #912018; }

.test-cards { border-top: 1px solid var(--border); padding-top: var(--space-3); font: var(--text-sm); color: var(--text-2); }
.test-cards summary { cursor: pointer; font-weight: 600; border-radius: var(--radius-1); }
.test-cards p { margin-top: var(--space-2); color: var(--text-muted); }
.test-cards ul { list-style: none; display: grid; gap: var(--space-2); margin-top: var(--space-3); }
.test-cards li { display: flex; flex-wrap: wrap; gap: var(--space-1) var(--space-3); align-items: baseline; }
.test-cards code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; color: var(--text); }

.thread-notice { flex: none; padding: var(--space-2) var(--space-4); background: var(--warning-bg); border-bottom: 1px solid var(--note-border); color: var(--warning); font: var(--text-sm); }
.thread-notice .link-btn { color: var(--warning); font: inherit; font-weight: 600; }
.composer-reason .link-btn { color: var(--warning); font: inherit; font-weight: 600; }

@media (max-width: 639px) {
  .billing { grid-column: 2 / -1; }
  .billing-inner { padding: var(--space-4) var(--space-3) var(--space-6); }
  .bill-card { padding: var(--space-4); }
  .bill-facts { grid-template-columns: 1fr; }
  .field-row { grid-template-columns: 1fr; }
}
E
cd ..; npx tsc --noEmit && npx vite build 2>&1 | tail -5; rm -rf dist
